/**
 * Stage 3 test pack: the planted problems in tests/fixtures/scan must give
 * exactly the expected issues and counts (no missing and no extra issues).
 * Files are generated by scripts/fixtures/make_scan_pack.ts (+ make_scan_xlsx.py).
 */
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { EngineCore } from "../../src/engine/core.ts";

const DIR = new URL("../fixtures/scan/", import.meta.url);
const expected = JSON.parse(readFileSync(new URL("expected.json", DIR), "utf8")) as Record<string, Record<string, number>>;

for (const [name, counts] of Object.entries(expected)) {
  test(`${name}: exactly the planted problems`, async () => {
    const core = new EngineCore();
    const s = await core.open(new File([readFileSync(new URL(name, DIR))], name), name.endsWith(".xlsx") ? "xlsx" : "csv", {}, () => {});
    assert.equal(s.headerGuess, true, "header row detected");
    const r = await core.scan(s.activeSheet, { headerRow: true }, () => {});
    const got = Object.fromEntries(r.issues.map((i) => [i.id, i.count]));
    assert.deepEqual(got, counts);
  });
}
